SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
SELECT set_config('variant.details',(current_setting('media.product_details')::jsonb-'media_sources'||'{"images":["https://example.test/legacy.png"]}')::text,true);
SELECT set_config('variant.rows',(current_setting('media.product_variants')::jsonb||'[{"id":"90000000-0000-0000-0000-000000000002","sku":"ISOLATED-MEDIA-OTHER","variant_name":"Other","cost_price":1,"sale_price":2,"stock":0,"minimum_stock":0}]')::text,true);
SET LOCAL ROLE authenticated;
SELECT public.save_admin_sales_product(gen_random_uuid(),'30000000-0000-0000-0000-000000000001',(SELECT updated_at FROM public.product WHERE id='30000000-0000-0000-0000-000000000001'),current_setting('variant.details')::jsonb,current_setting('variant.rows')::jsonb);
SELECT set_config('variant.session',public.prepare_variant_media_upload(gen_random_uuid(),'30000000-0000-0000-0000-000000000001',null,'90000000-0000-0000-0000-000000000001',100,'image/png','variant.png')->>'session_id',true);
SELECT set_config('variant.lease',public.claim_media_upload(current_setting('variant.session')::uuid)->>'lease',true);
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('variant.asset',public.finish_media_upload(current_setting('variant.session')::uuid,current_setting('variant.lease')::uuid,'10000000-0000-0000-0000-000000000001',repeat('e',64),2,2)::text,true);
RESET ROLE;
SELECT pg_temp.expect_error($q$INSERT INTO public.product_media(product_id,media_asset_id) VALUES('30000000-0000-0000-0000-000000000001',current_setting('variant.asset')::uuid)$q$,'42501');
SELECT set_config('variant.rows',jsonb_set(current_setting('variant.rows')::jsonb,'{0,media_sources}',jsonb_build_array(jsonb_build_object('asset_id',current_setting('variant.asset'))))::text,true);
SET LOCAL ROLE authenticated;
SELECT public.save_admin_sales_product(gen_random_uuid(),'30000000-0000-0000-0000-000000000001',(SELECT updated_at FROM public.product WHERE id='30000000-0000-0000-0000-000000000001'),current_setting('variant.details')::jsonb,current_setting('variant.rows')::jsonb);
RESET ROLE;
SELECT set_config('variant.ref',(SELECT id::text FROM public.product_variant_media WHERE media_asset_id=current_setting('variant.asset')::uuid),true);
SELECT pg_temp.assert((SELECT status='attached' FROM public.media_asset WHERE id=current_setting('variant.asset')::uuid),'variant attached by real product RPC');
SET LOCAL ROLE authenticated;
SELECT public.save_admin_sales_product(gen_random_uuid(),'30000000-0000-0000-0000-000000000001',(SELECT updated_at FROM public.product WHERE id='30000000-0000-0000-0000-000000000001'),current_setting('variant.details')::jsonb,current_setting('variant.rows')::jsonb);
SELECT pg_temp.expect_error($q$SELECT public.save_admin_sales_product(gen_random_uuid(),'30000000-0000-0000-0000-000000000001',(SELECT updated_at FROM public.product WHERE id='30000000-0000-0000-0000-000000000001'),current_setting('variant.details')::jsonb,jsonb_set(current_setting('variant.rows')::jsonb,'{1,media_sources}',jsonb_build_array(jsonb_build_object('asset_id',current_setting('variant.asset')))))$q$,'42501');
RESET ROLE;
SELECT pg_temp.assert((SELECT id::text=current_setting('variant.ref') FROM public.product_variant_media WHERE media_asset_id=current_setting('variant.asset')::uuid),'retained reference ID unchanged');
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claim.sub','',true);
SELECT pg_temp.assert((public.resolve_media_asset(current_setting('variant.asset')::uuid)->>'public')::boolean,'published variant public');
SELECT pg_temp.assert(EXISTS(SELECT 1 FROM jsonb_array_elements(public.customer_shop_catalog()) p,jsonb_array_elements(p->'product_variant') v WHERE v->>'id'='90000000-0000-0000-0000-000000000001' AND v->'image_urls'->>0='/api/media?action=read&id='||current_setting('variant.asset')),'catalog resolves variant image');
RESET ROLE;
UPDATE public.product_variant SET status='inactive' WHERE id='90000000-0000-0000-0000-000000000001';
SET LOCAL ROLE anon;
SELECT pg_temp.assert(public.resolve_media_asset(current_setting('variant.asset')::uuid) IS NULL,'inactive variant hidden');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
SELECT pg_temp.expect_error($q$SELECT public.prepare_variant_media_upload(gen_random_uuid(),'30000000-0000-0000-0000-000000000001',null,'90000000-0000-0000-0000-000000000001',100,'image/png','bad.png')$q$,'42501');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
DELETE FROM public.product_variant_media WHERE media_asset_id=current_setting('variant.asset')::uuid;
SELECT pg_temp.assert((SELECT state='pending_delete' FROM public.media_upload_session WHERE id=current_setting('variant.session')::uuid),'detached variant queues cleanup');
SET LOCAL ROLE authenticated;
SELECT set_config('variant.draft_session',public.prepare_variant_media_upload(gen_random_uuid(),null,'30000000-0000-0000-0000-000000000003','90000000-0000-0000-0000-000000000003',100,'image/png','draft.png')->>'session_id',true);
SELECT set_config('variant.draft_lease',public.claim_media_upload(current_setting('variant.draft_session')::uuid)->>'lease',true);
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('variant.draft_asset',public.finish_media_upload(current_setting('variant.draft_session')::uuid,current_setting('variant.draft_lease')::uuid,'10000000-0000-0000-0000-000000000001',repeat('f',64),2,2)::text,true);
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT public.save_admin_sales_product(gen_random_uuid(),'30000000-0000-0000-0000-000000000003',null,
 jsonb_set(current_setting('variant.details')::jsonb,'{slug}','"isolated-new-variant"'),
 jsonb_build_array(jsonb_build_object('id','90000000-0000-0000-0000-000000000003','sku','ISOLATED-NEW-VARIANT','variant_name','New','cost_price',1,'sale_price',2,'stock',0,'minimum_stock',0,'media_sources',jsonb_build_array(jsonb_build_object('asset_id',current_setting('variant.draft_asset'))))));
RESET ROLE;
SELECT pg_temp.assert((SELECT product_id='30000000-0000-0000-0000-000000000003'::uuid AND state='attached' FROM public.media_upload_session WHERE id=current_setting('variant.draft_session')::uuid),'draft product and variant adopted atomically');
